            /** @description Unauthorized */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["V1ErrorWrapper"];
                };
            };
            /** @description Forbidden */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "*/*": components["schemas"]["V1ErrorWrapper"];
                };
            };
            /** @description Drop or collection not found for the given slug. Code DROP_NOT_FOUND. */
